const response = $input.first().json;
const text = response.choices?.[0]?.message?.content || '{}';
const incoming = $('Build Router Context').first().json;

let routing = {};
try {
  routing = JSON.parse(text.replace(/```json?/g, '').replace(/```/g, '').trim());
} catch(e) {
  routing = { intent: 'greeting', confidence: 0.5, agent: 'sales_agent', urgency: 'medium', needs_human: false };
}

if (routing.confidence < 0.6) { routing.needs_human = true; routing.agent = 'human_escalation'; }

return [{ json: { ...incoming, intent: routing.intent, confidence: routing.confidence, target_agent: routing.agent, urgency: routing.urgency, needs_human: routing.needs_human, routing_reasoning: routing.reasoning || '' } }];

