const input = $input.first().json;

let fullResponse = '';
let metadata = '';

if (input.choices) {
  fullResponse = input.choices[0]?.message?.content || '';
} else if (input.ai_response) {
  fullResponse = input.ai_response;
  metadata = input.metadata_line || '';
}

if (!metadata) {
  const metaMatch = fullResponse.match(/\[STAGE:(\w+)\|FOLLOWUP:(\d+)\|SCORE_DELTA:([+-]?\d+)\]/);
  if (metaMatch) {
    metadata = metaMatch[0];
    fullResponse = fullResponse.replace(metaMatch[0], '').trim();
  }
}

let stage = '', followUpHours = 24, scoreDelta = 0;
const parsed = metadata.match(/STAGE:(\w+)\|FOLLOWUP:(\d+)\|SCORE_DELTA:([+-]?\d+)/);
if (parsed) { stage = parsed[1]; followUpHours = parseInt(parsed[2]); scoreDelta = parseInt(parsed[3]); }

const context = $('Build Router Context').first().json;

return [{ json: {
  lead_id: context.lead_id, phone: context.phone, name: context.name,
  response_message: fullResponse,
  suggested_stage: stage || context.stage,
  follow_up_hours: followUpHours,
  score_delta: scoreDelta,
  new_score: Math.min(100, Math.max(0, (parseInt(context.score) || 0) + scoreDelta)),
  target_agent: context.target_agent, intent: context.intent,
  notify_admin: input.notify_admin || false,
  escalation_reason: input.escalation_reason || ''
} }];
